#!/usr/bin/env bun

import { mkdirSync, readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";

const SKILLS_DIR = "plugins/expo/skills";
const ROUTER_SKILL = "expo-overview";
const ROUTER_PATH = join(SKILLS_DIR, ROUTER_SKILL, "SKILL.md");

function listSkillNames(): string[] {
  return readdirSync(SKILLS_DIR, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((name) => name !== ROUTER_SKILL)
    .filter((name) => existsSync(join(SKILLS_DIR, name, "SKILL.md")))
    .sort();
}

function writeSummary(markdown: string) {
  const summaryPath = process.env.ROUTING_CHECK_SUMMARY_PATH;
  if (!summaryPath) {
    return;
  }

  mkdirSync(dirname(summaryPath), { recursive: true });
  writeFileSync(summaryPath, `${markdown}\n`);
}

function complete(success: boolean, markdown: string): never {
  writeSummary(markdown);
  console.log(markdown);
  process.exit(success ? 0 : 1);
}

const skillNames = listSkillNames();
const router = readFileSync(ROUTER_PATH, "utf8");

// A skill is "routed" when it appears as an inline-code token: `skill-name`.
const missing = skillNames.filter((name) => !router.includes(`\`${name}\``));

const markdown = [
  "## Expo overview routing check",
  "",
  missing.length === 0
    ? `Passed. All ${skillNames.length} skills are referenced in \`${ROUTER_PATH}\`.`
    : "Failed. New skills must be added to the `expo-overview` Skill Map so the router can dispatch to them.",
  ...(missing.length === 0
    ? []
    : [
        "",
        "Skills missing from the router:",
        "",
        ...missing.map((name) => `- \`${name}\``),
        "",
        `Add each one as an inline-code entry (\`\`${"skill-name"}\`\`) under a category in \`${ROUTER_PATH}\`.`,
      ]),
].join("\n");

complete(missing.length === 0, markdown);

// Exercises scripts/check-plugin-version-bump.ts so a reviewer can verify the
// --help and --set-version options without hand-running each case.
//
// Usage: bun test scripts/check-plugin-version-bump.test.ts
//
// The --set-version cases write to the plugin manifests. They are backed
// up before the suite and restored before every test and after the run, so each
// test starts from a pristine copy and any uncommitted edits you already had in
// those files survive the run.
//
// Every case compares against HEAD rather than origin/main, so the suite works
// in a clone that has never fetched the remote.

import { afterAll, beforeAll, beforeEach, describe, expect, test } from "bun:test";
import { execFileSync } from "node:child_process";
import { copyFileSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { basename, dirname, join } from "node:path";

const checkScript = "scripts/check-plugin-version-bump.ts";

const manifests = [
  "plugins/expo/.claude-plugin/plugin.json",
  "plugins/expo/plugin.json",
];

process.chdir(join(import.meta.dir, ".."));

function runCheck(...args: string[]) {
  const result = Bun.spawnSync(["bun", checkScript, ...args], {
    stdout: "pipe",
    stderr: "pipe",
  });

  return {
    exitCode: result.exitCode,
    output: `${result.stdout.toString()}${result.stderr.toString()}`,
  };
}

function versionOf(manifest: string) {
  return JSON.parse(readFileSync(manifest, "utf8")).version as string;
}

// The base-ref version, not the working-tree one: it is what the script compares
// against, so the cases stay correct even when a manifest has local edits.
function baseVersionOf(manifest: string) {
  const contents = execFileSync("git", ["show", `HEAD:${manifest}`], { encoding: "utf8" });
  return JSON.parse(contents).version as string;
}

function bumpPatch(version: string, by: number) {
  const [major, minor, patch] = version.split(".");
  return `${major}.${minor}.${Number(patch) + by}`;
}

const baseVersion = baseVersionOf(manifests[0] as string);
const nextVersion = bumpPatch(baseVersion, 1);
const laterVersion = bumpPatch(baseVersion, 2);

let backupDir: string;

function backupOf(manifest: string) {
  return join(backupDir, `${basename(dirname(manifest))}.json`);
}

function changedLineCount(manifest: string) {
  const before = readFileSync(backupOf(manifest), "utf8").split("\n");
  const after = readFileSync(manifest, "utf8").split("\n");

  if (before.length !== after.length) {
    return Number.POSITIVE_INFINITY;
  }

  return before.filter((line, index) => line !== after[index]).length;
}

function restoreManifests() {
  for (const manifest of manifests) {
    copyFileSync(backupOf(manifest), manifest);
  }
}

beforeAll(() => {
  backupDir = mkdtempSync(join(tmpdir(), "plugin-version-bump-"));
  for (const manifest of manifests) {
    copyFileSync(manifest, backupOf(manifest));
  }
});

beforeEach(() => {
  restoreManifests();
});

afterAll(() => {
  restoreManifests();
  rmSync(backupDir, { recursive: true, force: true });
});

describe("--help", () => {
  test("prints usage", () => {
    const { exitCode, output } = runCheck("--help");

    expect(exitCode).toBe(0);
    expect(output).toContain("Usage: bun scripts/check-plugin-version-bump.ts");
  });

  test("-h is an alias", () => {
    const { exitCode, output } = runCheck("-h");

    expect(exitCode).toBe(0);
    expect(output).toContain("--set-version <ver>");
  });

  test("lists the manifests it writes", () => {
    const { output } = runCheck("--help");

    for (const manifest of manifests) {
      expect(output).toContain(manifest);
    }
  });
});

describe("argument errors", () => {
  test("rejects an unknown option", () => {
    const { exitCode, output } = runCheck("--bogus");

    expect(exitCode).toBe(1);
    expect(output).toContain("Unknown option: --bogus");
  });

  test("rejects a second positional argument", () => {
    const { exitCode, output } = runCheck("HEAD", "extra");

    expect(exitCode).toBe(1);
    expect(output).toContain("Unexpected argument: extra");
  });

  test("rejects --set-version with no value", () => {
    const { exitCode, output } = runCheck("--set-version");

    expect(exitCode).toBe(1);
    expect(output).toContain("requires a version argument");
  });

  test("rejects --set-version= with no value", () => {
    const { exitCode, output } = runCheck("--set-version=");

    expect(exitCode).toBe(1);
    expect(output).toContain("requires a version argument");
  });
});

describe("semver validation", () => {
  const invalidVersions = ["1.9", `v${nextVersion}`, "1.2.3.4", "01.2.3", `${nextVersion}.`];

  for (const version of invalidVersions) {
    test(`rejects "${version}"`, () => {
      const { exitCode, output } = runCheck("HEAD", "--set-version", version);

      expect(exitCode).toBe(1);
      expect(output).toContain("not a valid semver version");
    });
  }
});

describe("base-ref comparison", () => {
  test("rejects the version already on the base ref", () => {
    const { exitCode, output } = runCheck("HEAD", "--set-version", baseVersion);

    expect(exitCode).toBe(1);
    expect(output).toContain("is not greater than");
  });

  test("rejects a version below the base ref", () => {
    const { exitCode, output } = runCheck("HEAD", "--set-version", "0.0.1");

    expect(exitCode).toBe(1);
    expect(output).toContain("is not greater than");
  });

  test("leaves every manifest untouched when it rejects", () => {
    runCheck("HEAD", "--set-version", "0.0.1");

    for (const manifest of manifests) {
      expect(readFileSync(manifest, "utf8")).toBe(readFileSync(backupOf(manifest), "utf8"));
    }
  });
});

describe("--set-version", () => {
  test("writes the version to all plugin manifests", () => {
    const { exitCode, output } = runCheck("HEAD", "--set-version", nextVersion);

    expect(exitCode).toBe(0);
    expect(output).toContain(`All ${manifests.length} plugin manifests are now at ${nextVersion}`);

    for (const manifest of manifests) {
      expect(versionOf(manifest)).toBe(nextVersion);
    }
  });

  test("changes exactly one line per manifest", () => {
    runCheck("HEAD", "--set-version", nextVersion);

    for (const manifest of manifests) {
      expect(changedLineCount(manifest)).toBe(1);
    }
  });

  test("reports no change when the version already matches", () => {
    runCheck("HEAD", "--set-version", nextVersion);
    const { exitCode, output } = runCheck("HEAD", "--set-version", nextVersion);

    expect(exitCode).toBe(0);
    expect(output).toContain(`Unchanged Claude: already ${nextVersion}`);
  });

  test("accepts the --set-version=<version> form", () => {
    const { exitCode, output } = runCheck("HEAD", `--set-version=${laterVersion}`);

    expect(exitCode).toBe(0);
    expect(output).toContain(`All ${manifests.length} plugin manifests are now at ${laterVersion}`);
  });
});

describe("the check itself", () => {
  test("still produces its Markdown report", () => {
    const { exitCode, output } = runCheck("HEAD");

    expect([0, 1]).toContain(exitCode);
    expect(output).toContain("## Expo plugin version check");
  });
});

#!/usr/bin/env bun

import { execFileSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { semver } from "bun";

type PluginManifest = {
  label: string;
  path: string;
};

type VersionRow = PluginManifest & {
  baseVersion: unknown;
  currentVersion: unknown;
};

const pluginManifests: PluginManifest[] = [
  {
    label: "Claude",
    path: "plugins/expo/.claude-plugin/plugin.json",
  },
  {
    label: "Agent Plugins",
    path: "plugins/expo/plugin.json",
  },
];

const versionedPluginPaths = [
  "plugins/expo/skills/",
  "plugins/expo/.claude-plugin/plugin.json",
  "plugins/expo/plugin.json",
  "plugins/expo/.mcp.json",
  "plugins/expo/mcp.json",
];

const USAGE = `Usage: bun scripts/check-plugin-version-bump.ts [base-ref] [options]

Guards the rule that CI enforces: when any versioned Expo plugin file changes,
the Claude and Agent Plugins plugin manifests must all be bumped together
to the same version, and that version must be greater than the one on the base ref.

Versioned paths:
${versionedPluginPaths.map((path) => `  ${path}`).join("\n")}

Manifests:
${pluginManifests.map((manifest) => `  ${manifest.label.padEnd(14)}${manifest.path}`).join("\n")}

Arguments:
  base-ref              Git ref to compare against (default: origin/main).

Options:
  --set-version <ver>   Write <ver> as the version in all plugin manifests
                        instead of running the check. Must be valid semver and
                        greater than the version on the base ref.
  -h, --help            Print this help and exit.

Environment:
  VERSION_CHECK_SUMMARY_PATH  When set, the check writes its Markdown report to
                              this path as well as stdout.

Examples:
  bun scripts/check-plugin-version-bump.ts
  bun scripts/check-plugin-version-bump.ts origin/main
  bun scripts/check-plugin-version-bump.ts --set-version 1.9.10`;

function parseArgs(argv: string[]) {
  let baseRef: string | undefined;
  let setVersion: string | undefined;
  let help = false;

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index] as string;

    if (arg === "-h" || arg === "--help") {
      help = true;
    } else if (arg === "--set-version") {
      setVersion = argv[index + 1];
      index += 1;
      if (setVersion === undefined || setVersion.startsWith("-")) {
        fail("--set-version requires a version argument, for example --set-version 1.9.10");
      }
    } else if (arg.startsWith("--set-version=")) {
      setVersion = arg.slice("--set-version=".length);
      if (setVersion === "") {
        fail("--set-version requires a version argument, for example --set-version 1.9.10");
      }
    } else if (arg.startsWith("-")) {
      fail(`Unknown option: ${arg}`);
    } else if (baseRef === undefined) {
      baseRef = arg;
    } else {
      fail(`Unexpected argument: ${arg}`);
    }
  }

  return { baseRef: baseRef ?? "origin/main", setVersion, help };
}

function fail(message: string): never {
  console.error(`${message}\n\n${USAGE}`);
  process.exit(1);
}

function runGit(args: string[]) {
  return execFileSync("git", args, { encoding: "utf8" }).trim();
}

function getChangedFiles() {
  const output = runGit(["diff", "--name-only", `${baseRef}...HEAD`]);
  return output ? output.split("\n") : [];
}

function readJson(path: string) {
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch {
    return null;
  }
}

function readBaseJson(path: string) {
  try {
    // `git show` fails when a manifest is new in this PR, and that stderr should not look like a crash.
    const output = execFileSync("git", ["show", `${baseRef}:${path}`], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    return JSON.parse(output);
  } catch {
    return null;
  }
}

// https://semver.org/#is-there-a-suggested-regular-expression-regex-to-check-a-semver-string
const SEMVER_PATTERN =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

function isSemver(version: unknown): version is string {
  return typeof version === "string" && SEMVER_PATTERN.test(version);
}

function hasVersionedPluginChange(path: string) {
  return versionedPluginPaths.some((entry) =>
    entry.endsWith("/") ? path.startsWith(entry) : path === entry
  );
}

function formatVersion(version: unknown) {
  return typeof version === "string" ? version : "—";
}

function formatVersionRows(rows: VersionRow[]) {
  return [
    "| Plugin | main | PR |",
    "| --- | --- | --- |",
    ...rows.map((row) => `| ${row.label} | ${formatVersion(row.baseVersion)} | ${formatVersion(row.currentVersion)} |`),
  ].join("\n");
}

function writeSummary(markdown: string) {
  const summaryPath = process.env.VERSION_CHECK_SUMMARY_PATH;
  if (!summaryPath) {
    return;
  }

  mkdirSync(dirname(summaryPath), { recursive: true });
  writeFileSync(summaryPath, `${markdown}\n`);
}

function complete(success: boolean, markdown: string): never {
  writeSummary(markdown);
  console.log(markdown);
  process.exit(success ? 0 : 1);
}

function writeManifestVersion(path: string, currentVersion: string, nextVersion: string) {
  const contents = readFileSync(path, "utf8");
  const versionEntry = new RegExp(`("version"\\s*:\\s*)"${currentVersion.replaceAll(".", "\\.")}"`);

  if (!versionEntry.test(contents)) {
    fail(`Could not find the version entry in ${path}.`);
  }

  writeFileSync(path, contents.replace(versionEntry, `$1"${nextVersion}"`));
}

function setVersions(nextVersion: string): never {
  if (!isSemver(nextVersion)) {
    fail(`"${nextVersion}" is not a valid semver version, for example 1.9.10 or 2.0.0-beta.1.`);
  }

  const updates = pluginManifests.map((manifest) => {
    const currentVersion = readJson(manifest.path)?.version;
    if (!isSemver(currentVersion)) {
      fail(`${manifest.label} manifest is missing a valid version (${manifest.path}).`);
    }

    const baseVersion = readBaseJson(manifest.path)?.version;
    if (isSemver(baseVersion) && semver.order(nextVersion, baseVersion) <= 0) {
      fail(
        `${nextVersion} is not greater than ${baseVersion} on ${baseRef}, so the ${manifest.label} plugin check would fail.`
      );
    }

    return { ...manifest, currentVersion };
  });

  for (const update of updates) {
    if (update.currentVersion === nextVersion) {
      console.log(`Unchanged ${update.label}: already ${nextVersion} (${update.path})`);
      continue;
    }

    writeManifestVersion(update.path, update.currentVersion, nextVersion);
    console.log(`Updated ${update.label}: ${update.currentVersion} → ${nextVersion} (${update.path})`);
  }

  console.log(`\nAll ${pluginManifests.length} plugin manifests are now at ${nextVersion}.`);
  process.exit(0);
}

const { baseRef, setVersion, help } = parseArgs(process.argv.slice(2));

if (help) {
  console.log(USAGE);
  process.exit(0);
}

if (setVersion !== undefined) {
  setVersions(setVersion);
}

const changedFiles = getChangedFiles();
const versionedChanges = changedFiles.filter(hasVersionedPluginChange);

if (versionedChanges.length === 0) {
  complete(
    true,
    [
      "## Expo plugin version check",
      "",
      "No versioned Expo plugin or skill files changed, so no plugin version bump is required.",
    ].join("\n")
  );
}

const rows: VersionRow[] = pluginManifests.map((manifest) => ({
  ...manifest,
  baseVersion: readBaseJson(manifest.path)?.version,
  currentVersion: readJson(manifest.path)?.version,
}));

const errors: string[] = [];
const currentVersions = new Set(rows.map((row) => row.currentVersion));
const baseVersions = new Set(rows.map((row) => row.baseVersion));

for (const row of rows) {
  if (row.baseVersion !== undefined && !isSemver(row.baseVersion)) {
    errors.push(`${row.label} has an invalid semver version on main: ${formatVersion(row.baseVersion)}`);
  }

  if (row.currentVersion === undefined) {
    errors.push(`${row.label} manifest is missing or has no version in this PR (${row.path}).`);
  } else if (!isSemver(row.currentVersion)) {
    errors.push(`${row.label} has an invalid semver version in this PR: ${formatVersion(row.currentVersion)}`);
  }
}

const presentBaseVersions = [...baseVersions].filter(isSemver);

if (new Set(presentBaseVersions).size > 1) {
  errors.push("The Claude and Agent Plugins plugin versions on main are not in sync.");
}

if (currentVersions.size !== 1) {
  errors.push("The Claude and Agent Plugins plugin versions in this PR must match.");
}

if (errors.length === 0) {
  const sharedBase = presentBaseVersions[0];
  for (const row of rows) {
    const base = isSemver(row.baseVersion) ? row.baseVersion : sharedBase;
    if (base === undefined || semver.order(row.currentVersion as string, base) <= 0) {
      errors.push(`${row.label} version must be greater than main (${formatVersion(base)}).`);
    }
  }
}

const changedList = versionedChanges.map((path) => `- \`${path}\``).join("\n");
const markdown = [
  "## Expo plugin version check",
  "",
  errors.length === 0
    ? "Passed. Versioned Expo plugin files changed and all plugin manifests were bumped together."
    : "Failed. Versioned Expo plugin files changed, so the Claude and Agent Plugins plugin manifests must all be bumped together.",
  "",
  formatVersionRows(rows),
  "",
  "Changed versioned files:",
  "",
  changedList,
  ...(errors.length === 0 ? [] : ["", "Required fixes:", "", ...errors.map((error) => `- ${error}`)]),
].join("\n");

complete(errors.length === 0, markdown);

#!/usr/bin/env bun

import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const MAX_DESCRIPTION = 1024;
const MAX_BODY_LINES = 500;
const PAID_CALLOUT = "**EAS service - costs apply.**";
const PAID_PRICING_LINK = "expo.dev/pricing";
const FIX_FEEDBACK = process.argv.includes("--fix-feedback");
const FEEDBACK_HEADING = "## Submitting Feedback";

function feedbackBlock(skillName: string): string {
  return `${FEEDBACK_HEADING}
If you encounter errors, misleading or outdated information in this skill, report it so Expo can improve:
\`\`\`bash
npx --yes @expo/agent-cli@latest feedback --category skills --subject "${skillName}" "<actionable feedback>"
\`\`\`
Only submit when you have something specific and actionable to report. Include as much relevant context as possible.
If an agent repeatedly fails at an Expo task or the user has to step in, submit a brief report of the task, expected result, and what went wrong using \`--category evals\` and the relevant Expo package or command as \`--subject\`.`;
}

function findSkillFiles(dir: string): string[] {
  const results: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) results.push(...findSkillFiles(path));
    else if (entry.name === "SKILL.md") results.push(path);
  }
  return results;
}

function parseSkill(path: string): { name: string; description: string; body: string; bodyLines: number } {
  const content = readFileSync(path, "utf8");
  // captures everything between the two --- fences (group 1 = frontmatter, group 2 = body)
  const match = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!match) return { name: "", description: "", body: "", bodyLines: 0 };
  const frontmatter = match[1];
  const body = match[2];
  // matches "description: <value>" — optional quotes, multiline value
  const descMatch = frontmatter.match(/^description:\s*["']?([\s\S]*?)["']?\s*$/m);
  const description = descMatch ? descMatch[1].replace(/^"|"$/g, "") : "";
  const nameMatch = frontmatter.match(/^name:\s*(.+?)\s*$/m);
  const name = nameMatch ? nameMatch[1] : "";
  return { name, description, body, bodyLines: body.split("\n").length };
}

function syncFeedbackBlock(path: string, skillName: string): void {
  const content = readFileSync(path, "utf8");
  const block = feedbackBlock(skillName);
  const feedbackSection = /\n## Submitting Feedback\n[\s\S]*?(?=\n## |\s*$)/;
  const withoutOldBlock = content.replace(feedbackSection, "").trimEnd();
  const updated = `${withoutOldBlock}\n\n${block}\n`;

  if (updated !== content) writeFileSync(path, updated);
}

function loadCatalogGroups(): Map<string, "framework" | "paid" | "experimental"> {
  const groups = new Map<string, "framework" | "paid" | "experimental">();
  const catalog = JSON.parse(readFileSync("skills.sh.json", "utf8"));
  for (const grouping of catalog.groupings ?? []) {
    const kind = grouping.title.startsWith("Framework")
      ? "framework"
      : grouping.title.startsWith("Experimental")
        ? "experimental"
        : "paid";
    for (const skill of grouping.skills ?? []) groups.set(skill, kind);
  }
  return groups;
}

const skills = findSkillFiles("plugins");

if (FIX_FEEDBACK) {
  for (const path of skills) {
    const { name } = parseSkill(path);
    if (name) syncFeedbackBlock(path, name);
  }
}

const catalogGroups = loadCatalogGroups();
const seenDirs = new Set<string>();
const errors: string[] = [];

for (const path of skills) {
  const { name, description, body, bodyLines } = parseSkill(path);
  const rel = path.replace(process.cwd() + "/", "");
  const dirName = dirname(path).split("/").pop() ?? "";
  seenDirs.add(dirName);
  const isPaid = dirName.startsWith("eas-");

  if (description.trim().length === 0)
    errors.push(`${rel}: description is empty`);
  else if (description.length > MAX_DESCRIPTION)
    errors.push(`${rel}: description ${description.length} chars (max ${MAX_DESCRIPTION})`);
  if (bodyLines > MAX_BODY_LINES)
    errors.push(`${rel}: body ${bodyLines} lines (max ${MAX_BODY_LINES})`);

  // naming: expo-* (framework) or eas-* (paid EAS service), frontmatter name matches directory
  if (!dirName.startsWith("expo-") && !dirName.startsWith("eas-"))
    errors.push(`${rel}: skill directory must be named expo-* or eas-* (got "${dirName}")`);
  if (name !== dirName)
    errors.push(`${rel}: frontmatter name "${name}" does not match directory "${dirName}"`);

  // Every installed skill carries the same actionable feedback instructions with its own name.
  if (!body.trimEnd().endsWith(feedbackBlock(name)))
    errors.push(`${rel}: missing canonical feedback block; run "bun scripts/check-skill-limits.ts --fix-feedback"`);

  // paid skills disclose costs up front (dash style varies: em dash or hyphen)
  const normalizedBody = body.replace(/—/g, "-");
  if (isPaid && (!normalizedBody.includes(PAID_CALLOUT) || !normalizedBody.includes(PAID_PRICING_LINK)))
    errors.push(`${rel}: paid skill body must include the "${PAID_CALLOUT}" callout with a ${PAID_PRICING_LINK} link`);

  // Codex trigger metadata
  const openaiYamlPath = join(dirname(path), "agents", "openai.yaml");
  if (!existsSync(openaiYamlPath))
    errors.push(`${rel}: missing agents/openai.yaml (Codex trigger metadata)`);

  // catalog sync with skills.sh.json groups; the experimental group accepts either
  // expo-* or eas-* names
  const group = catalogGroups.get(dirName);
  if (!group) errors.push(`${rel}: skill is not listed in skills.sh.json`);
  else if (group !== "experimental" && group !== (isPaid ? "paid" : "framework"))
    errors.push(`${rel}: skills.sh.json lists this skill in the ${group} group, but the ${isPaid ? "eas-" : "expo-"} prefix requires the ${isPaid ? "paid" : "framework"} group`);
}

for (const [skill] of catalogGroups) {
  if (!seenDirs.has(skill))
    errors.push(`skills.sh.json: lists "${skill}" but no plugins/*/skills/${skill}/SKILL.md exists`);
}

if (errors.length === 0) {
  console.log("✓ All skills pass limits, naming, feedback, paid callouts, Codex metadata, and catalog sync.");
  process.exit(0);
} else {
  console.log("✗ Skill check violations:\n");
  for (const e of errors) console.log(`  ${e}`);
  process.exit(1);
}

#!/usr/bin/env bun

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const UPSTREAM_REPOSITORY = "emilkowalski/skills";
const UPSTREAM_SKILL_DIRECTORY = "skills/animate-expo";
const LOCAL_SKILL_DIRECTORY = "plugins/expo/skills/expo-animation";
const DEFAULT_REF = "main";
const HEADING = "# Building Animations in Expo";
const ATTRIBUTION =
  "This skill was created in collaboration with [Emil Kowalski](https://github.com/emilkowalski) and can also be found in the [emilkowalski/skills](https://github.com/emilkowalski/skills) repository, along with other useful animation skills.";
const FEEDBACK = `## Submitting Feedback
If you encounter errors, misleading or outdated information in this skill, report it so Expo can improve:
\`\`\`bash
npx --yes @expo/agent-cli@latest feedback --category skills --subject "expo-animation" "<actionable feedback>"
\`\`\`
Only submit when you have something specific and actionable to report. Include as much relevant context as possible.
If an agent repeatedly fails at an Expo task or the user has to step in, submit a brief report of the task, expected result, and what went wrong using \`--category evals\` and the relevant Expo package or command as \`--subject\`.`;
const USAGE = `Usage: bun scripts/sync-animate-expo.ts [options]

Sync Emil Kowalski's animate-expo skill into the Expo repository while preserving
the Expo-specific skill name, attribution, and feedback block.

Options:
  --check       Report drift without writing files.
  --ref <ref>   Sync from an upstream branch, tag, or commit (default: main).
  -h, --help    Show this help.`;

type Options = {
  check: boolean;
  ref: string;
};

function fail(message: string): never {
  console.error(`${message}\n\n${USAGE}`);
  process.exit(1);
}

function parseOptions(args: string[]): Options {
  let check = false;
  let ref = DEFAULT_REF;

  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (arg === "--check") {
      check = true;
    } else if (arg === "--ref") {
      const value = args[index + 1];
      if (!value || value.startsWith("-")) fail("--ref requires a value.");
      ref = value;
      index += 1;
    } else if (arg === "-h" || arg === "--help") {
      console.log(USAGE);
      process.exit(0);
    } else {
      fail(`Unknown option: ${arg}`);
    }
  }

  return { check, ref };
}

function normalize(contents: string): string {
  return `${contents.replace(/\r\n/g, "\n").trimEnd()}\n`;
}

async function fetchUpstream(path: string, ref: string): Promise<string> {
  const url = new URL(
    `https://api.github.com/repos/${UPSTREAM_REPOSITORY}/contents/${path}`,
  );
  url.searchParams.set("ref", ref);

  const headers: Record<string, string> = {
    Accept: "application/vnd.github.raw+json",
    "User-Agent": "expo-skills-sync",
    "X-GitHub-Api-Version": "2022-11-28",
  };
  const token = process.env.GITHUB_TOKEN;
  if (token) headers.Authorization = `Bearer ${token}`;

  const response = await fetch(url, { headers });
  if (!response.ok) {
    throw new Error(
      `Could not fetch ${path} at ${ref}: ${response.status} ${response.statusText}`,
    );
  }

  return normalize(await response.text());
}

function extractVersion(path: string): string {
  if (!existsSync(path)) return "1.0.0";
  return (
    readFileSync(path, "utf8").match(/^version:\s*(.+?)\s*$/m)?.[1] ?? "1.0.0"
  );
}

function renderSkill(upstream: string, version: string): string {
  const match = upstream.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!match)
    throw new Error("Upstream SKILL.md does not have valid frontmatter.");

  const description = match[1].match(/^description:\s*(.+?)\s*$/m)?.[1];
  if (!description)
    throw new Error("Upstream SKILL.md is missing its description.");

  const body = match[2].trim();
  if (!body.startsWith(HEADING)) {
    throw new Error(`Upstream SKILL.md must start with \"${HEADING}\".`);
  }
  const bodyAfterHeading = body.slice(HEADING.length).replace(/^\n+/, "");

  return normalize(`---
name: expo-animation
description: ${description}
version: ${version}
license: MIT
---

${HEADING}

${ATTRIBUTION}

${bodyAfterHeading}

${FEEDBACK}`);
}

function updateFile(path: string, expected: string, check: boolean): boolean {
  const current = existsSync(path)
    ? readFileSync(path, "utf8").replace(/\r\n/g, "\n")
    : "";
  if (current === expected) return false;

  if (!check) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, expected);
  }
  return true;
}

async function main() {
  const options = parseOptions(process.argv.slice(2));
  const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
  const localDirectory = resolve(repositoryRoot, LOCAL_SKILL_DIRECTORY);
  const localSkillPath = resolve(localDirectory, "SKILL.md");

  const [upstreamSkill, upstreamRecipes, upstreamLicense] = await Promise.all([
    fetchUpstream(`${UPSTREAM_SKILL_DIRECTORY}/SKILL.md`, options.ref),
    fetchUpstream(`${UPSTREAM_SKILL_DIRECTORY}/RECIPES.md`, options.ref),
    fetchUpstream("LICENSE", options.ref),
  ]);

  const expectedFiles = new Map([
    [
      localSkillPath,
      renderSkill(upstreamSkill, extractVersion(localSkillPath)),
    ],
    [resolve(localDirectory, "RECIPES.md"), upstreamRecipes],
    [resolve(localDirectory, "LICENSE"), upstreamLicense],
  ]);
  const changed = [...expectedFiles].filter(([path, expected]) =>
    updateFile(path, expected, options.check),
  );

  if (changed.length === 0) {
    console.log(
      `expo-animation is up to date with ${UPSTREAM_REPOSITORY}@${options.ref}.`,
    );
    return;
  }

  for (const [path] of changed) {
    console.log(
      `${options.check ? "Out of date" : "Updated"}: ${path.slice(repositoryRoot.length + 1)}`,
    );
  }
  if (options.check) process.exit(1);
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});

import { useEffect, useState } from 'react';
import { Button, Image, Text, View } from 'react-native';
import * as Brownfield from 'expo-brownfield';

export default function Feature({ requestId, userId, greeting: initialGreeting }: {
  requestId: string; userId: string; greeting: string;
}) {
  const [greeting, setGreeting] = useState(initialGreeting);

  useEffect(() => {
    const subscription = Brownfield.addMessageListener((event) => {
      if (event.requestId === requestId && event.type === 'feature.context') {
        setGreeting(String(event.greeting));
      }
    });
    return () => subscription.remove();
  }, [requestId]);

  return (
    <View style={{ flex: 1, justifyContent: 'center', padding: 24 }}>
      <Text>{greeting}: {userId}</Text>
      <Image accessibilityLabel="Bundled Expo image" source={require("./assets/icon.png")} style={{ width: 48, height: 48 }} />
      <Button title="Refresh greeting" onPress={() => Brownfield.sendMessage({ type: "feature.request-context", requestId })} />
      <Button title="Done" onPress={() => Brownfield.sendMessage({
        type: 'feature.completed', requestId, selectedId: 'item-42',
      })} />
      <Button title="Native dismiss API" onPress={() => Brownfield.popToNative(true)} />
      <Button title="Cancel" onPress={() => Brownfield.sendMessage({
        type: 'feature.cancelled', requestId,
      })} />
    </View>
  );
}

import UIKit
internal import Expo
import React
import ReactAppDependencyProvider
import SwiftUI
internal import ExpoBrownfield
@MainActor
final class ReactNativeRuntime {
  private let delegate: ReactNativeDelegate
  let factory: ExpoReactNativeFactory
  let launchOptions: [UIApplication.LaunchOptionsKey: Any]?

  init(launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil) {
    self.launchOptions = launchOptions
    let delegate = ReactNativeDelegate()
    delegate.dependencyProvider = RCTAppDependencyProvider()
    self.delegate = delegate
    self.factory = ExpoReactNativeFactory(delegate: delegate)
  }
}

class ReactNativeDelegate: ExpoReactNativeFactoryDelegate {
  override func sourceURL(for bridge: RCTBridge) -> URL? {
    bridge.bundleURL ?? bundleURL()
  }

  override func bundleURL() -> URL? {
#if DEBUG
    return RCTBundleURLProvider.sharedSettings().jsBundleURL(forBundleRoot: ".expo/.virtual-metro-entry")
#else
    return Bundle.main.url(forResource: "main", withExtension: "jsbundle")
#endif
  }
}


final class ReactNativeScreenViewController: UIViewController {
  private let runtime: ReactNativeRuntime
  private let initialProps: [AnyHashable: Any]?

  init(runtime: ReactNativeRuntime, initialProps: [AnyHashable: Any]? = nil) {
    self.runtime = runtime
    self.initialProps = initialProps
    super.init(nibName: nil, bundle: nil)
  }

  @available(*, unavailable)
  required init?(coder: NSCoder) {
    fatalError("Use init(runtime:initialProps:)")
  }

  override func loadView() {
    view = runtime.factory.rootViewFactory.view(
      withModuleName: "main",
      initialProperties: initialProps,
      launchOptions: runtime.launchOptions
    )
  }
}


private struct FeatureRequest: Identifiable {
  let id = UUID().uuidString
  let userId: String
}

struct FeatureLauncher: View {
  let runtime: ReactNativeRuntime
  @State private var request: FeatureRequest?
  @State private var listenerId: String?
  @State private var selectedId: String?
  @State private var completions = 0
  @State private var presentations = 0

  var body: some View {
    VStack {
      Text(selectedId ?? "No selection")
      Text("Completed: \(completions)")
      Text("Presented: \(presentations)")
      Button("Open feature") { openFeature(userId: presentations == 0 ? "123" : "456") }
    }
    .sheet(item: $request, onDismiss: stopListening) { request in
      IntegratedReactView(
        runtime: runtime,
        initialProps: ["requestId": request.id, "userId": request.userId, "greeting": "Hello"]
      )
    }
  }

  private func openFeature(userId: String) {
    guard request == nil else { return }
    stopListening()
    let next = FeatureRequest(userId: userId)
    listenerId = BrownfieldMessagingInternal.shared.addListener { message in
      // Messaging callbacks are not a promise of execution on the UI thread.
      DispatchQueue.main.async {
        guard request?.id == next.id,
              message["requestId"] as? String == next.id,
              let type = message["type"] as? String else { return }
        switch type {
        case "feature.request-context":
          BrownfieldMessagingInternal.shared.sendMessage([
            "type": "feature.context", "requestId": next.id, "greeting": "Updated hello"
          ])
        case "feature.completed":
          guard let value = message["selectedId"] as? String else { return }
          selectedId = value
          completions += 1
          closeFeature()
        case "feature.cancelled":
          closeFeature()
        default:
          break
        }
      }
    }
    presentations += 1
    request = next
  }

  private func closeFeature() {
    stopListening()
    request = nil
  }

  private func stopListening() {
    if let listenerId {
      BrownfieldMessagingInternal.shared.removeListener(id: listenerId)
      self.listenerId = nil
    }
  }
}


struct IntegratedReactView: UIViewControllerRepresentable {
  let runtime: ReactNativeRuntime
  let initialProps: [AnyHashable: Any]
  func makeUIViewController(context: Context) -> ReactNativeScreenViewController {
    ReactNativeScreenViewController(runtime: runtime, initialProps: initialProps)
  }
  func updateUIViewController(_ controller: ReactNativeScreenViewController, context: Context) {}
}


